#!/usr/bin/env python3
"""simcompare 단일 파일 실행기 (자동 생성: scripts/build_single_file.py). 소스 해시 d3d167426d5e21a1aef3da2ea3b576e99d3210ee84edb5e44c0f93872f87aced.
서버 wrapper가 명령줄 인자를 넘기지 못할 때 쓴다. 아래 EDIT 블록만 고치고 이 파일을 그대로 실행한다."""
# 5회차(DL2 경로 전용): 직접 대응(4회차의 direct/roi_correspondence.json)을 쓰면 이 회차를 건너뛴다.
# 다른 제품 탐색이 필요할 때만 쓴다: DL2 baseline_ncc 결과(ncc_r2t.json, ncc_t2r.json)와 sheet.html을 보고 쓴
# decisions.csv(헤더 candidate_id,decision,note; decision=accept|reject)가 필요하다.
# --match 파일은 baseline_ncc 결과(psdl2_baseline_ncc_v1) 또는 DL2 search 배치 봉투(psdl2_search_batch_v1)를 읽는다. 배치 봉투는 방향마다 따로 줄 수도 있고, DL2 가 쓴 search_batch.json 하나를 두 --match 에 같이 줄 수도 있다.
# 첫 작업(--list)은 candidate_id 목록을 로그에 찍는다. decisions.csv가 없으면 둘째 작업이 종료 코드 2로 멈춘다.
# --labelled-by(확정한 사용자 ID)와 --mutual-tolerance-um은 필수이며 기본값이 없다. 값은 예시다.
# ============================== EDIT BELOW: 이 블록만 고치세요 ==============================
# 각 작업은 `python -m simcompare <명령> <인자...>`와 같다. 명령 이름은 import-hotspots, validate-data, compare,
# electrode-map, import-electrode-assets, export-review-rois, candidates-change, candidates, confirm-pairs, compare-windows, report 등이다.
# 인자는 명령줄에서 쓰던 그대로 문자열 리스트로 적는다. 상대 경로는 BASE_DIR 기준이다(아래). wrapper가 이 파일을 다른 곳에
# 복사해 실행하면 "이 .py가 있는 폴더"가 달라지므로, 상대 경로를 쓸 때는 BASE_DIR를 절대 경로로 적는 것이 안전하다.
# 작업은 위에서부터 차례로 실행된다. 종료 코드 0(완료)과 3(부분 결과)은 다음 작업으로 넘어가고, 그 밖의 코드는 멈춘다.
JOBS = [
    # candidate_id 목록만 출력
    ('confirm-pairs', [
        '--list',
        '--config', 'real.yaml',
        '--candidates', 'data/changes',
        '--match', 'reference_to_target=data/dl2/ncc_r2t.json',
        '--match', 'target_to_reference=data/dl2/ncc_t2r.json',
    ]),
    # accept 후보만 roi_correspondence.json으로. --labelled-by CHANGE_ME를 실제 ID로 바꾼다
    ('confirm-pairs', [
        '--config', 'real.yaml',
        '--candidates', 'data/changes',
        '--match', 'reference_to_target=data/dl2/ncc_r2t.json',
        '--match', 'target_to_reference=data/dl2/ncc_t2r.json',
        '--decisions', 'data/dl2/decisions.csv',
        '--labelled-by', 'CHANGE_ME',
        '--mutual-tolerance-um', '5',
        '--out', 'data/confirmed',
    ]),
]
LOG_FILE = 'runs/simcompare_5_confirm_pairs.log'   # stdout/stderr를 이 파일에도 남긴다. 필요 없으면 None
WORK_DIR = None                               # 패키지를 풀 폴더. None이면 이 파일 옆, 쓸 수 없으면 임시 폴더
BASE_DIR = None                               # JOBS·LOG_FILE·WORK_DIR의 상대 경로 기준 폴더(절대 경로). None이면 이 .py가 있는 폴더
# ============================== EDIT ABOVE ==============================================

